namespace ghidra.graph.exporter;




using org.jgrapht.nio.json;

using ghidra.service.graph;

public class JsonGraphExporter : AbstractAttributedGraphExporter {

	/* @Override */
	public void exportGraph(AttributedGraph graph, File file)
    {
		JSONExporter<AttributedVertex, AttributedEdge> exporter =
			new(vertexIdProvider);

		exporter.setVertexAttributeProvider(this.getAttributes);
		exporter.setEdgeAttributeProvider(this.getAttributes);
		exporter.setEdgeIdProvider(edgeIdProvider);
		try {
			exporter.exportGraph(graph, file);
		}
		catch (Exception e) {
			throw new IOException(e);
		}
	}

	/* @Override */
	public string getFileExtension() {
		return "json";
	}

	/* @Override */
	public string getName() {
		return "JSON";
	}

	/* @Override */
	public string getDesciption() {
		return "JGraphT library export of a graph to a JSON file";
	}

}
